import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React from 'react';
import Header from './components/Header';
import Hero from './components/Hero';
import Stats from './components/Stats';
import Products from './components/Products';
import Marquee from './components/Marquee';
import Services from './components/Services';
import Footer from './components/Footer';

const App: React.FC = () => {
  return (
    <div className="bg-[#050a15] min-h-screen text-white">
      <Header />
      <main>
        <Hero />
        <Stats />
        <Products />
        <Marquee />
        <Services />
      </main>
      <Footer />
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Zap, Menu, X } from 'lucide-react';

const Header: React.FC = () => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 30);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <header 
      id="main-header" 
      className={`fixed w-full z-50 top-0 transition-all duration-500 border-b border-white/5 ${
        isScrolled 
          ? 'bg-[#050a15]/95 shadow-2xl py-2 backdrop-blur-xl' 
          : 'bg-[#050a15]/80 py-4 backdrop-blur-xl'
      }`}
    >
      <div className="max-w-7xl mx-auto px-6 flex justify-between items-center">
        {/* Logo Section */}
        <a href="#home" className="flex items-center group" aria-label="Voltar para o topo">
          <img 
            src="https://i.imgur.com/xqZ3B58.png" 
            alt="Logo Volts Baterias" 
            className="h-12 md:h-14 object-contain transition-transform duration-300 group-hover:scale-105"
            onError={(e) => {
              e.currentTarget.style.display = 'none';
              e.currentTarget.nextElementSibling?.classList.remove('hidden');
            }}
          />
          <div className="hidden flex items-center gap-2">
            <div className="w-10 h-10 bg-[#00f2ff] rounded flex items-center justify-center">
              <Zap className="text-[#050a15]" />
            </div>
            <span className="font-bold text-xl font-heading">VOLTS</span>
          </div>
        </a>

        {/* Desktop Nav */}
        <nav className="hidden md:flex gap-10 text-[11px] font-bold uppercase tracking-[0.2em] text-gray-400">
          <a href="#home" className="hover:text-[#00f2ff] transition-colors">Início</a>
          <a href="#about" className="hover:text-[#00f2ff] transition-colors">A Loja</a>
          <a href="#products" className="hover:text-[#00f2ff] transition-colors">Produtos</a>
          <a href="#services" className="hover:text-[#00f2ff] transition-colors">Serviços</a>
          <a href="#contact" className="hover:text-[#00f2ff] transition-colors">WhatsApp</a>
        </nav>

        {/* Mobile Menu Toggle */}
        <button 
          className="md:hidden text-white"
          onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
        >
          {isMobileMenuOpen ? <X /> : <Menu />}
        </button>

        <button className="hidden md:block px-6 py-2 border border-[#00f2ff]/50 text-[#00f2ff] rounded-full text-[10px] font-bold uppercase tracking-widest hover:bg-[#00f2ff] hover:text-[#050a15] transition-all duration-300">
          Emergência 24h
        </button>
      </div>

      {/* Mobile Nav */}
      {isMobileMenuOpen && (
        <div className="md:hidden absolute top-full left-0 w-full bg-[#050a15] border-b border-white/10 p-6 flex flex-col gap-4 shadow-2xl">
           <a href="#home" onClick={() => setIsMobileMenuOpen(false)} className="text-sm font-bold uppercase tracking-widest text-gray-300 hover:text-[#00f2ff]">Início</a>
           <a href="#about" onClick={() => setIsMobileMenuOpen(false)} className="text-sm font-bold uppercase tracking-widest text-gray-300 hover:text-[#00f2ff]">A Loja</a>
           <a href="#products" onClick={() => setIsMobileMenuOpen(false)} className="text-sm font-bold uppercase tracking-widest text-gray-300 hover:text-[#00f2ff]">Produtos</a>
           <a href="#services" onClick={() => setIsMobileMenuOpen(false)} className="text-sm font-bold uppercase tracking-widest text-gray-300 hover:text-[#00f2ff]">Serviços</a>
           <a href="#contact" onClick={() => setIsMobileMenuOpen(false)} className="text-sm font-bold uppercase tracking-widest text-gray-300 hover:text-[#00f2ff]">WhatsApp</a>
           <button className="w-full py-3 bg-[#00f2ff] text-[#050a15] rounded font-bold uppercase tracking-widest text-xs">
              Emergência 24h
           </button>
        </div>
      )}
    </header>
  );
};

export default Header;

